def miller_rabin_deterministic_round(n: int, a: int) -> bool:
    val_n = int(abs(n))
    if val_n < 2:
        return False
    if val_n == 2:
        return True
    if val_n % 2 == 0:
        return False
    base = int(abs(a)) % val_n
    if base == 0:
        return True
    d = val_n - 1
    s = 0
    while d % 2 == 0:
        d = d // 2
        s = s + 1
    x = pow(base, d, val_n)
    if x == 1 or x == val_n - 1:
        return True
    for _ in range(s - 1):
        x = x * x % val_n
        if x == val_n - 1:
            return True
    return False

def lucas_lehmer_mersenne_test(p: int) -> bool:
    exp = int(abs(p))
    if exp < 2:
        return False
    if exp == 2:
        return True
    capped_p = min(exp, 61)
    m = (1 << capped_p) - 1
    s = 4
    for _ in range(capped_p - 2):
        s = (s * s - 2) % m
    is_prime = s == 0
    return is_prime

def pollard_p_minus_1_factor(n: int, b_bound: int) -> int:
    val_n = int(abs(n))
    if val_n <= 3:
        return val_n if val_n > 0 else 1
    if val_n % 2 == 0:
        return 2
    b = max(2, min(int(abs(b_bound)), 100))
    a = 2
    for j in range(2, b + 1):
        a = pow(a, j, val_n)
        u = abs(a - 1)
        v = val_n
        while v != 0:
            u, v = (v, u % v)
        if 1 < u < val_n:
            return u
    return 1

def fermat_factorization_step(n: int, max_iter: int) -> tuple[int, int]:
    val_n = int(abs(n))
    if val_n <= 3:
        return (1, max(1, val_n))
    if val_n % 2 == 0:
        return (2, val_n // 2)
    limit = max(10, min(int(abs(max_iter)), 5000))
    a = int(math.isqrt(val_n))
    if a * a < val_n:
        a = a + 1
    for _ in range(limit):
        b2 = a * a - val_n
        b = int(math.isqrt(b2))
        if b * b == b2:
            p = a - b
            q = a + b
            return (min(p, q), max(p, q))
        a = a + 1
    return (1, val_n)

def shanks_tonelli_modular_sqrt(n: int, p: int) -> int:
    val_p = int(abs(p))
    if val_p <= 2:
        return int(n) % val_p if val_p > 0 else 0
    val_n = int(n) % val_p
    if val_n == 0:
        return 0
    if pow(val_n, (val_p - 1) // 2, val_p) != 1:
        return -1
    q = val_p - 1
    s = 0
    while q % 2 == 0:
        q = q // 2
        s = s + 1
    if s == 1:
        r = pow(val_n, (val_p + 1) // 4, val_p)
        return min(r, val_p - r)
    z = 2
    while pow(z, (val_p - 1) // 2, val_p) != val_p - 1:
        z = z + 1
        if z > 100:
            break
    m = s
    c = pow(z, q, val_p)
    t = pow(val_n, q, val_p)
    r = pow(val_n, (q + 1) // 2, val_p)
    while t != 1:
        t2i = t
        i = 0
        for idx in range(1, m):
            t2i = t2i * t2i % val_p
            if t2i == 1:
                i = idx
                break
        if i == 0:
            return -1
        b = pow(c, 1 << m - i - 1, val_p)
        m = i
        c = b * b % val_p
        t = t * c % val_p
        r = r * b % val_p
    return min(r, val_p - r)

def jacobi_symbol_computation(a: int, n: int) -> int:
    val_n = int(abs(n))
    if val_n == 0 or val_n % 2 == 0:
        return 0
    val_a = int(a) % val_n
    t = 1
    while val_a != 0:
        while val_a % 2 == 0:
            val_a = val_a // 2
            r = val_n % 8
            if r == 3 or r == 5:
                t = -t
        val_a, val_n = (val_n, val_a)
        if val_a % 4 == 3 and val_n % 4 == 3:
            t = -t
        val_a = val_a % val_n
    return t if val_n == 1 else 0

def legendre_symbol_euler_criterion(a: int, p: int) -> int:
    val_p = int(abs(p))
    if val_p < 3 or val_p % 2 == 0:
        return 0
    val_a = int(a) % val_p
    if val_a == 0:
        return 0
    res = pow(val_a, (val_p - 1) // 2, val_p)
    if res == 1:
        return 1
    if res == val_p - 1:
        return -1
    return 0

def discrete_log_baby_step_giant_step(g: int, h: int, p: int) -> int:
    val_p = int(abs(p))
    if val_p <= 2:
        return 0
    val_g = int(g) % val_p
    val_h = int(h) % val_p
    if val_h == 1:
        return 0
    m = int(math.isqrt(val_p)) + 1
    table = {}
    cur = 1
    for j in range(m):
        if cur not in table:
            table[cur] = j
        cur = cur * val_g % val_p
    factor = pow(cur, val_p - 2, val_p)
    gamma = val_h
    for i in range(m + 1):
        if gamma in table:
            return i * m + table[gamma]
        gamma = gamma * factor % val_p
    return -1

def euler_totient_phi_factorized(prime_factors: list[int]) -> int:
    clean = [int(abs(x)) for x in prime_factors if int(abs(x)) > 1]
    if not clean:
        return 1
    counts = {}
    for p in clean:
        counts[p] = counts.get(p, 0) + 1
    phi = 1
    for p, k in counts.items():
        phi = phi * (p - 1) * p ** (k - 1)
    return phi

def mobius_inversion_mu(prime_factors: list[int]) -> int:
    clean = [int(abs(x)) for x in prime_factors if int(abs(x)) > 1]
    if not clean:
        return 1
    seen = set()
    for p in clean:
        if p in seen:
            return 0
        seen.add(p)
    count = len(clean)
    return -1 if count % 2 == 1 else 1

def divisor_sigma_function(prime_factors: list[int], k: int) -> int:
    power = max(0, int(k))
    clean = [int(abs(x)) for x in prime_factors if int(abs(x)) > 1]
    if not clean:
        return 1
    counts = {}
    for p in clean:
        counts[p] = counts.get(p, 0) + 1
    sigma = 1
    for p, a in counts.items():
        if power == 0:
            sigma = sigma * (a + 1)
        else:
            num = p ** (power * (a + 1)) - 1
            den = p ** power - 1
            sigma = sigma * (num // den)
    return sigma

def carmichael_lambda_function(prime_factor_powers: list[list[int]]) -> int:
    if not prime_factor_powers:
        return 1
    factors = []
    for pair in prime_factor_powers:
        if isinstance(pair, (list, tuple)) and len(pair) >= 2:
            p = int(abs(pair[0]))
            k = int(abs(pair[1]))
            if p > 1 and k > 0:
                factors.append((p, k))
    if not factors:
        return 1
    lcm_val = 1
    for p, k in factors:
        if p == 2:
            if k == 1:
                lam = 1
            elif k == 2:
                lam = 2
            else:
                lam = 1 << k - 2
        else:
            lam = (p - 1) * p ** (k - 1)
        u, v = (lcm_val, lam)
        while v != 0:
            u, v = (v, u % v)
        lcm_val = lcm_val * lam // u
    return lcm_val

def primitive_root_check(g: int, p: int, prime_factors_p_minus_1: list[int]) -> bool:
    val_p = int(abs(p))
    if val_p <= 2:
        return False
    base = int(g) % val_p
    if base <= 1:
        return False
    distinct_factors = set((int(abs(q)) for q in prime_factors_p_minus_1 if int(abs(q)) > 1))
    if not distinct_factors:
        return False
    order = val_p - 1
    for q in distinct_factors:
        if pow(base, order // q, val_p) == 1:
            return False
    return True

def sieve_of_eratosthenes_range(start: int, stop: int) -> list[int]:
    s = max(2, int(start))
    e = max(s, min(int(stop), s + 500))
    limit = int(math.isqrt(e)) + 1
    base_sieve = [True] * (limit + 1)
    base_primes = []
    for p in range(2, limit + 1):
        if base_sieve[p]:
            base_primes.append(p)
            for multiple in range(p * p, limit + 1, p):
                base_sieve[multiple] = False
    length = e - s + 1
    seg_sieve = [True] * length
    for p in base_primes:
        first = (s + p - 1) // p * p
        start_idx = max(first, p * p)
        for m in range(start_idx, e + 1, p):
            seg_sieve[m - s] = False
    primes = []
    for idx in range(length):
        if seg_sieve[idx]:
            primes.append(s + idx)
    return primes

def stern_brocot_fraction_tree(path: str) -> tuple[int, int]:
    p_str = str(path).upper()
    l_num, l_den = (0, 1)
    r_num, r_den = (1, 0)
    for char in p_str:
        m_num = l_num + r_num
        m_den = l_den + r_den
        if char == 'L':
            r_num, r_den = (m_num, m_den)
        elif char == 'R':
            l_num, l_den = (m_num, m_den)
    final_num = l_num + r_num
    final_den = l_den + r_den
    return (final_num, final_den)

def quaternion_conjugate_norm(q: list[float]) -> tuple[list[float], float]:
    v = [float(x) for x in q] if len(q) >= 4 else [1.0, 0.0, 0.0, 0.0]
    w, x, y, z = (v[0], v[1], v[2], v[3])
    conj = [w, -x, -y, -z]
    sq_norm = w * w + x * x + y * y + z * z
    return (conj, sq_norm)

def polynomial_divmod_synthetic(dividend: list[float], divisor: list[float]) -> tuple[list[float], list[float]]:
    num = [float(x) for x in dividend] if dividend else [0.0]
    den = [float(x) for x in divisor] if divisor else [1.0]
    while len(den) > 1 and abs(den[-1]) < 1e-12:
        den.pop()
    lead = den[-1] if abs(den[-1]) > 1e-12 else 1.0
    rem = list(num)
    deg_num = len(rem) - 1
    deg_den = len(den) - 1
    if deg_num < deg_den:
        return ([0.0], rem)
    quot = [0.0] * (deg_num - deg_den + 1)
    for i in range(deg_num - deg_den, -1, -1):
        factor = rem[i + deg_den] / lead
        quot[i] = factor
        for j in range(deg_den + 1):
            rem[i + j] = rem[i + j] - factor * den[j]
    while len(rem) > 1 and abs(rem[-1]) < 1e-12:
        rem.pop()
    return (quot, rem)

def polynomial_gcd_euclidean(p1: list[float], p2: list[float]) -> list[float]:
    a = [float(x) for x in p1] if p1 else [0.0]
    b = [float(x) for x in p2] if p2 else [0.0]
    while len(a) > 1 and abs(a[-1]) < 1e-12:
        a.pop()
    while len(b) > 1 and abs(b[-1]) < 1e-12:
        b.pop()
    step = 0
    while (len(b) > 1 or abs(b[0]) > 1e-12) and step < 20:
        rem = list(a)
        deg_a = len(rem) - 1
        deg_b = len(b) - 1
        if deg_a >= deg_b and abs(b[-1]) > 1e-12:
            lead = b[-1]
            for i in range(deg_a - deg_b, -1, -1):
                fac = rem[i + deg_b] / lead
                for j in range(deg_b + 1):
                    rem[i + j] = rem[i + j] - fac * b[j]
        while len(rem) > 1 and abs(rem[-1]) < 1e-12:
            rem.pop()
        a, b = (b, rem)
        step = step + 1
    lead_a = a[-1] if abs(a[-1]) > 1e-12 else 1.0
    monic = [coef / lead_a for coef in a]
    return monic

def polynomial_resultant_sylvester(p1: list[float], p2: list[float]) -> float:
    a = [float(x) for x in p1] if p1 else [0.0]
    b = [float(x) for x in p2] if p2 else [0.0]
    while len(a) > 1 and abs(a[-1]) < 1e-12:
        a.pop()
    while len(b) > 1 and abs(b[-1]) < 1e-12:
        b.pop()
    deg_a = len(a) - 1
    deg_b = len(b) - 1
    if deg_a <= 0 or deg_b <= 0:
        return float(a[0] ** max(1, deg_b) * b[0] ** max(1, deg_a))
    if deg_a == 1 and deg_b == 1:
        return float(a[1] * b[0] - a[0] * b[1])
    a0 = a[0]
    a1 = a[1] if deg_a >= 1 else 0.0
    a2 = a[2] if deg_a >= 2 else 0.0
    b0 = b[0]
    b1 = b[1] if deg_b >= 1 else 0.0
    b2 = b[2] if deg_b >= 2 else 0.0
    if deg_a == 2 and deg_b == 1:
        res = a2 * b0 ** 2 - a1 * b0 * b1 + a0 * b1 ** 2
        return float(res)
    if deg_a == 1 and deg_b == 2:
        res = b2 * a0 ** 2 - b1 * a0 * a1 + b0 * a1 ** 2
        return float(res)
    t1 = a2 * b0 - a0 * b2
    t2 = a2 * b1 - a1 * b2
    t3 = a1 * b0 - a0 * b1
    det = t1 * t1 - t2 * t3
    return float(det)

def berlekamp_massey_linear_recurrence(sequence: list[int], prime_mod: int) -> list[int]:
    p = max(2, int(abs(prime_mod)))
    s = [int(x) % p for x in sequence]
    n = len(s)
    if n == 0:
        return [1]
    c = [1]
    b = [1]
    l = 0
    m = 1
    inv_b = 1
    for i in range(n):
        d = s[i]
        for j in range(1, l + 1):
            d = (d + c[j] * s[i - j]) % p
        if d == 0:
            m = m + 1
        else:
            t = list(c)
            fac = d * pow(inv_b, p - 2, p) % p
            deg_needed = len(b) + m
            while len(c) < deg_needed:
                c.append(0)
            for k in range(len(b)):
                c[k + m] = (c[k + m] - fac * b[k]) % p
            if 2 * l <= i:
                l = i + 1 - l
                b = t
                inv_b = d
                m = 1
            else:
                m = m + 1
    return [coef % p for coef in c]

def integer_square_root_newton(n: int) -> int:
    val = int(n)
    if val <= 0:
        return 0
    if val < 4:
        return 1
    x0 = 1 << (val.bit_length() + 1) // 2
    while True:
        x1 = (x0 + val // x0) // 2
        if x1 >= x0:
            return x0
        x0 = x1

def integer_cube_root_newton(n: int) -> int:
    val = int(n)
    if val <= 0:
        return 0
    if val < 8:
        return 1
    x0 = 1 << (val.bit_length() + 2) // 3
    while True:
        x1 = (2 * x0 + val // (x0 * x0)) // 3
        if x1 >= x0:
            return x0
        x0 = x1

def catalan_number_mod(n: int, m: int) -> int:
    mod = max(1, int(abs(m)))
    idx = max(0, int(n))
    if mod == 1:
        return 0
    if idx <= 1:
        return 1 % mod
    num = 1
    for k in range(2, idx + 1):
        num = num * (idx + k) // k
    return num % mod

def bell_number_triangle(n: int) -> int:
    idx = max(0, min(int(abs(n)), 25))
    if idx <= 1:
        return 1
    row = [1]
    for i in range(1, idx):
        next_row = [row[-1]]
        for j in range(i):
            next_row.append(next_row[j] + row[j])
        row = next_row
    return row[-1]

def stirling_number_second_kind(n: int, k: int) -> int:
    n_val = max(0, int(n))
    k_val = max(0, int(k))
    if k_val > n_val or k_val < 0:
        return 0
    if k_val == 0:
        return 1 if n_val == 0 else 0
    if k_val == 1 or k_val == n_val:
        return 1
    dp = [0] * (k_val + 1)
    dp[0] = 1
    for i in range(1, n_val + 1):
        next_dp = [0] * (k_val + 1)
        for j in range(1, min(i, k_val) + 1):
            next_dp[j] = j * dp[j] + dp[j - 1]
        dp = next_dp
    return dp[k_val]

def partitions_integer_euler(n: int) -> int:
    val = int(n)
    if val < 0:
        return 0
    if val <= 1:
        return 1
    limit = min(val, 60)
    p = [0] * (limit + 1)
    p[0] = 1
    for i in range(1, limit + 1):
        total = 0
        k = 1
        while True:
            g1 = k * (3 * k - 1) // 2
            g2 = k * (3 * k + 1) // 2
            if g1 > i and g2 > i:
                break
            sign = 1 if k % 2 == 1 else -1
            if g1 <= i:
                total = total + sign * p[i - g1]
            if g2 <= i:
                total = total + sign * p[i - g2]
            k = k + 1
        p[i] = total
    return p[limit]

def frobenius_coin_problem_two(a: int, b: int) -> int:
    val_a = int(a)
    val_b = int(b)
    if val_a <= 1 or val_b <= 1:
        return -1
    u, v = (val_a, val_b)
    while v != 0:
        u, v = (v, u % v)
    if u != 1:
        return -1
    g_val = val_a * val_b - val_a - val_b
    return g_val
